-- Run in Supabase SQL Editor. Create admin user in Authentication > Users, then whitelist their UUID below.
create table if not exists public.admin_users (user_id uuid primary key references auth.users(id) on delete cascade);
create table if not exists public.site_settings (key text primary key, value text not null default '');
create table if not exists public.projects (id bigint generated by default as identity primary key, title text not null, category text default '', description text default '', image text default '', url text default '', sort integer default 0, published boolean default false);
create table if not exists public.testimonials (id bigint generated by default as identity primary key, name text not null, role text default '', body text default '', published boolean default false);
create table if not exists public.leads (id bigint generated by default as identity primary key, name text not null, contact text not null, service text default '', message text default '', status text default 'new', created_at timestamptz default now());
create table if not exists public.lead_throttle (ip_hash text primary key, last_at timestamptz not null default now());
alter table public.admin_users enable row level security;
alter table public.site_settings enable row level security;
alter table public.projects enable row level security;
alter table public.testimonials enable row level security;
alter table public.leads enable row level security;
alter table public.lead_throttle enable row level security;
-- All access goes through server functions with the secret key; no anonymous table grants.
revoke all on public.admin_users, public.site_settings, public.projects, public.testimonials, public.leads, public.lead_throttle from anon, authenticated;
